#!/usr/bin/env bash
# Fails when a coverage spec of tests/e2e runs in no shard or in more than one shard.
#
# tests/e2e/coverage-shards.yaml is generated by tools/opgen. It lists a Ginkgo label filter for
# each shard of the live coverage suite. The check asks Ginkgo, with --dry-run, which specs each
# filter selects, and compares that with the specs that the label "coverage" selects.
#
# usage: scripts/check-coverage-shards.sh
# GINKGO names the ginkgo binary (default bin/ginkgo). SHARDS_FILE names the shard file.
set -euo pipefail

root=$(git rev-parse --show-toplevel)
cd "$root"
ginkgo=${GINKGO:-bin/ginkgo}
shards_file=${SHARDS_FILE:-tests/e2e/coverage-shards.yaml}

if [[ ! -x "$ginkgo" ]]; then
  echo "ginkgo is missing: run 'make ginkgo' or set GINKGO" >&2
  exit 2
fi

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

# specs_for <label filter> prints the full text of each spec that would run, sorted.
specs_for() {
  if ! "$ginkgo" --dry-run --label-filter="$1" --json-report="$tmp/report.json" ./tests/e2e/ > "$tmp/ginkgo.log" 2>&1; then
    cat "$tmp/ginkgo.log" >&2
    exit 1
  fi
  jq -r '.[].SpecReports[]
    | select(.LeafNodeType == "It" and .State == "passed")
    | (.ContainerHierarchyTexts + [.LeafNodeText]) | join(" ")' "$tmp/report.json" | sort
}

specs_for coverage > "$tmp/all.txt"

: > "$tmp/shard-specs.txt"
# The shard file has a generator header of comment lines, then JSON.
while IFS=$'\t' read -r name filter; do
  specs_for "$filter" > "$tmp/shard.txt"
  echo "shard $name: $(wc -l < "$tmp/shard.txt" | tr -d ' ') specs"
  cat "$tmp/shard.txt" >> "$tmp/shard-specs.txt"
done < <(grep -v '^#' "$shards_file" | jq -r '.shards[] | [.name, .filter] | @tsv')

sort "$tmp/shard-specs.txt" > "$tmp/shard-sorted.txt"
status=0
missing=$(comm -23 "$tmp/all.txt" <(sort -u "$tmp/shard-sorted.txt"))
if [[ -n "$missing" ]]; then
  echo "coverage specs that run in no shard:" >&2
  echo "$missing" >&2
  status=1
fi
doubled=$(uniq -d "$tmp/shard-sorted.txt")
if [[ -n "$doubled" ]]; then
  echo "coverage specs that run in more than one shard:" >&2
  echo "$doubled" >&2
  status=1
fi
extra=$(comm -13 "$tmp/all.txt" <(sort -u "$tmp/shard-sorted.txt"))
if [[ -n "$extra" ]]; then
  echo "shard specs that are not coverage specs:" >&2
  echo "$extra" >&2
  status=1
fi
if [[ $status -eq 0 ]]; then
  echo "every coverage spec runs in exactly one shard ($(wc -l < "$tmp/all.txt" | tr -d ' ') specs)"
fi
exit $status
